import { useEffect, useMemo, useRef, useState, type CSSProperties } from "react";
import { createRoot } from "react-dom/client";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faArrowLeft, faArrowRight, faArrowsUpDown, faArrowUpRightFromSquare, faBan, faBell, faBellSlash, faBrain, faBuilding, faBullseye, faCheck, faCircleCheck, faCircleExclamation, faCircleMinus, faCode, faCodeBranch, faCopy, faDownload, faEye, faFlask, faGaugeHigh, faGear, faHammer, faHourglassHalf, faInbox, faListCheck, faLock, faMagnifyingGlass, faMugHot, faPaperPlane, faPlus, faStar, faTerminal, faTriangleExclamation, faUserLock, faUsers, faWandMagicSparkles, faWifi, faXmark, type IconDefinition } from "@fortawesome/free-solid-svg-icons";
import type { HubSnapshot, OrchestrationPlanRecord, Participant, RoomEvent, RunnerError, Task } from "@mireva/protocol";
import "@fontsource/poppins/latin-400.css";
import "@fontsource/poppins/latin-500.css";
import "@fontsource/poppins/latin-600.css";
import "@fontsource/poppins/latin-700.css";
import "@fontsource/poppins/latin-800.css";
import "./styles.css";
import "./sprites.css";
import "./monitor.css";
import "./runner-connect.css";
import "./office-sprites.css";
import "./workspace-pages.css";
import "./live-office.css";
import "./dashboard-theme.css";

const defaultHub = "https://mireva-hub.renatojosesfc.workers.dev";
const inviteParameters = new URLSearchParams(window.location.search);
const localProjectDirectory = import.meta.env.VITE_MIREVA_PROJECT_DIR ?? "";
const roomStorageKey = `mireva:room:${localProjectDirectory || window.location.pathname}`;
const initialHub = inviteParameters.get("hub") ?? localStorage.getItem("mireva:hub") ?? defaultHub;
const initialRoom = inviteParameters.get("room") ?? localStorage.getItem(roomStorageKey) ?? "";
const localAgentUrl = import.meta.env.VITE_MIREVA_AGENT_URL ?? "http://127.0.0.1:49325";
const localAgentToken = import.meta.env.VITE_MIREVA_AGENT_TOKEN ?? "";
const inviteBaseUrl = import.meta.env.VITE_MIREVA_INVITE_BASE_URL || window.location.origin;
type WorkspacePage = "office" | "orchestrator" | "inbox" | "tasks" | "team" | "git" | "errors" | "settings";
const workspacePages: WorkspacePage[] = ["office", "orchestrator", "inbox", "tasks", "team", "git", "errors", "settings"];
const initialPage = workspacePages.includes(window.location.hash.slice(1) as WorkspacePage) ? window.location.hash.slice(1) as WorkspacePage : "office";
const roles = ["GENERAL", "ORCHESTRATOR", "DEVELOPMENT", "RESEARCH", "TEST", "REVIEW"] as const;
const permissionProfiles = ["READ_ONLY", "PROJECT", "PROJECT_NETWORK", "FULL"] as const;
type PermissionProfile = (typeof permissionProfiles)[number];
function UiIcon({ icon, className }: { icon: IconDefinition; className?: string }) { return <FontAwesomeIcon aria-hidden="true" className={className} icon={icon} />; }
type DiagnosticResult = { ok: boolean; checkedAt: string; checks: Array<{ key: string; status: "ok" | "warning" | "error"; title: string; detail: string; fix?: string }> };
const permissionInfo: Record<PermissionProfile, { label: string; description: string }> = {
  READ_ONLY: { label: "Somente leitura", description: "Pode analisar o projeto, sem editar ou executar comandos." },
  PROJECT: { label: "Trabalhar no projeto", description: "Pode editar e executar ferramentas na pasta; publicação e internet continuam bloqueadas." },
  PROJECT_NETWORK: { label: "Projeto + internet", description: "Também permite pesquisa e acesso a URLs durante o trabalho." },
  FULL: { label: "Acesso ampliado", description: "Remove proteções de ferramentas, caminhos e URLs. Use apenas em ambiente controlado." },
};
const roleInfo: Record<(typeof roles)[number], { label: string; icon: IconDefinition; capabilities: string[] }> = {
  GENERAL: { label: "Geral", icon: faStar, capabilities: [] }, ORCHESTRATOR: { label: "Orquestrador", icon: faBullseye, capabilities: ["ORCHESTRATE"] }, DEVELOPMENT: { label: "Desenvolvimento", icon: faCode, capabilities: ["CODE", "GIT"] }, RESEARCH: { label: "Pesquisa", icon: faMagnifyingGlass, capabilities: ["RESEARCH"] }, TEST: { label: "Testes", icon: faFlask, capabilities: ["TEST"] }, REVIEW: { label: "Revisão", icon: faEye, capabilities: ["REVIEW", "GIT"] },
};
const stateInfo: Record<string, { label: string; color: string; icon: IconDefinition }> = {
  AVAILABLE: { label: "Disponível", color: "#55b9ff", icon: faCircleCheck }, THINKING: { label: "Pensando", color: "#90a8ff", icon: faBrain }, WORKING: { label: "Trabalhando", color: "#52e09d", icon: faHammer }, EXECUTING: { label: "Executando comando", color: "#48dfb0", icon: faTerminal }, RESEARCHING: { label: "Pesquisando", color: "#ffd85c", icon: faMagnifyingGlass }, TESTING: { label: "Testando", color: "#b08cff", icon: faFlask }, WAITING_PERMISSION: { label: "Aguardando permissão", color: "#ffab65", icon: faLock }, WAITING_APPROVAL: { label: "Aguardando aprovação", color: "#ffab65", icon: faHourglassHalf }, AUTH_REQUIRED: { label: "Login necessário", color: "#ff8a65", icon: faUserLock }, RATE_LIMITED: { label: "Limite atingido", color: "#f7ba55", icon: faGaugeHigh }, NO_NETWORK: { label: "Sem internet", color: "#ff7e88", icon: faWifi }, BLOCKED: { label: "Bloqueado", color: "#ff6876", icon: faBan }, DISCONNECTED: { label: "Desconectado", color: "#7d849b", icon: faCircleMinus },
};
const taskStates = ["BACKLOG", "READY", "CLAIMED", "RUNNING", "REVIEW", "DONE"];
const progressFor = (task?: Task) => !task ? 0 : ({ BACKLOG: 5, READY: 15, CLAIMED: 30, RUNNING: 58, REVIEW: 88, DONE: 100, FAILED: 100, BLOCKED: 38, CANCELLED: 100, WAITING_APPROVAL: 92 }[task.status] ?? 0);
const taskStateLabel = (status: string) => ({ BACKLOG: "Fila", READY: "Pronta", CLAIMED: "Assumida", RUNNING: "Em execução", REVIEW: "Em revisão", DONE: "Concluída" }[status] ?? status);
const spriteNames = ["renato", "codex", "copilot", "gemini", "qa"];
const pixelAvatarUrl = (seed: string) => `/sprites/${spriteNames[[...seed].reduce((total, char) => total + char.charCodeAt(0), 0) % spriteNames.length]}.svg`;
const usagePercent = (usage: Participant["usage"]) => usage ? Math.min(100, Math.round((usage.used / usage.limit) * 100)) : null;
const usageTone = (usage: Participant["usage"]) => { const percent = usagePercent(usage) ?? 0; return percent >= 90 ? "danger" : percent >= 70 ? "warning" : "safe"; };
const seenLabel = (value: string) => { const seconds = Math.max(0, Math.round((Date.now() - Date.parse(value)) / 1_000)); return seconds < 10 ? "agora" : seconds < 60 ? `há ${seconds}s` : seconds < 3_600 ? `há ${Math.floor(seconds / 60)} min` : `há ${Math.floor(seconds / 3_600)} h`; };

function App() {
  const [hub, setHub] = useState(initialHub);
  const [roomCode, setRoomCode] = useState(initialRoom);
  const [snapshot, setSnapshot] = useState<HubSnapshot | null>(null);
  const [events, setEvents] = useState<RoomEvent[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [page, setPage] = useState<WorkspacePage>(initialPage);
  const [showRunnerConnect, setShowRunnerConnect] = useState(false);
  const [showRoomSetup, setShowRoomSetup] = useState(!initialRoom);
  const [requestText, setRequestText] = useState("");
  const [error, setError] = useState("");
  const [soundEnabled, setSoundEnabled] = useState(() => localStorage.getItem("mireva:notification-sound") !== "off");
  const [notification, setNotification] = useState<string | null>(null);
  const seenAttention = useRef<Set<string> | null>(null);
  const notificationTimer = useRef<number | undefined>(undefined);
  const audioContext = useRef<AudioContext | null>(null);
  const navigate = (nextPage: WorkspacePage) => { setPage(nextPage); window.location.hash = nextPage; window.scrollTo({ top: 0, behavior: "smooth" }); };
  const load = async () => {
    if (!roomCode) return;
    try {
      const [room, log] = await Promise.all([
        fetch(`${hub}/rooms/${roomCode}`).then(async (response) => { if (!response.ok) throw new Error("Sala não encontrada"); return response.json() as Promise<HubSnapshot>; }),
        fetch(`${hub}/rooms/${roomCode}/events?after=0`).then(async (response) => { if (!response.ok) throw new Error("Não foi possível carregar os eventos"); return response.json() as Promise<RoomEvent[]>; }),
      ]);
      const normalizedRoom = { ...room, plans: room.plans ?? [] };
      setSnapshot(normalizedRoom); setEvents(log); setSelectedId((current) => current && normalizedRoom.participants.some((participant) => participant.id === current) ? current : null); setError("");
      localStorage.setItem("mireva:hub", hub); localStorage.setItem(roomStorageKey, roomCode);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível carregar a sala"); }
  };
  const createRoom = async (name: string, ownerName: string) => {
    try {
      const response = await fetch(`${hub}/rooms`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ name, ownerName }) });
      const result = await response.json() as { room?: { code: string }; error?: string };
      if (!response.ok || !result.room) throw new Error(result.error ?? "Não foi possível criar o escritório");
      setRoomCode(result.room.code);
      setShowRoomSetup(false);
      navigate("office");
      localStorage.setItem("mireva:hub", hub);
      localStorage.setItem(roomStorageKey, result.room.code);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível criar o escritório"); }
  };
  const enterRoom = (input: string) => {
    const fromLink = new URLSearchParams(input.includes("?") ? input.slice(input.indexOf("?") + 1) : "").get("room");
    const code = (fromLink ?? input).replace(/[^a-z0-9]/gi, "").slice(-8).toUpperCase();
    if (code.length !== 8) { setError("Informe o código de 8 caracteres ou cole o convite da sala."); return; }
    setRoomCode(code); setShowRoomSetup(false); setError(""); navigate("office");
  };
  useEffect(() => { void load(); const timer = window.setInterval(() => void load(), 2_500); return () => window.clearInterval(timer); }, [hub, roomCode]);
  useEffect(() => { const syncPage = () => { const next = window.location.hash.slice(1) as WorkspacePage; if (workspacePages.includes(next)) setPage(next); }; window.addEventListener("hashchange", syncPage); return () => window.removeEventListener("hashchange", syncPage); }, []);
  const assigned = useMemo(() => new Map(snapshot?.tasks.filter((task) => task.assignedParticipantId && !["DONE", "CANCELLED", "FAILED"].includes(task.status)).map((task) => [task.assignedParticipantId!, task])), [snapshot]);
  const selected = selectedId ? snapshot?.participants.find((person) => person.id === selectedId) : undefined;
  const selectedTask = selected ? assigned.get(selected.id) : undefined;
  const officeRunners = snapshot?.participants.filter((person) => person.agent !== "human" && person.role !== "ORCHESTRATOR") ?? [];
  const idleRunners = officeRunners.filter((person) => person.state === "AVAILABLE" && !assigned.get(person.id));
  const desks = Array.from({ length: 5 }, (_, index) => officeRunners[index] ?? null);
  const activeCount = snapshot?.participants.filter((person) => person.agent !== "human" && person.state !== "DISCONNECTED").length ?? 0;
  const runnerErrors = events.filter((event) => event.kind === "RUNNER_ERROR");
  const answeredRequests = new Set(events.filter((event) => event.kind === "ORCHESTRATOR_RESPONSE").map((event) => String(event.payload.requestEventId ?? "")));
  const decisionCount = (snapshot?.plans.filter((plan) => plan.status === "DRAFT").length ?? 0) + (snapshot?.tasks.filter((task) => ["REVIEW", "WAITING_APPROVAL"].includes(task.status)).length ?? 0) + events.filter((event) => event.kind === "ORCHESTRATOR_REQUEST" && !answeredRequests.has(event.id)).length;
  const attentionItems = useMemo(() => snapshot ? [
    ...snapshot.plans.filter((plan) => plan.status === "DRAFT").map((plan) => ({ key: `plan:${plan.id}`, message: "Um novo plano está aguardando sua aprovação." })),
    ...snapshot.tasks.filter((task) => task.status === "REVIEW").map((task) => ({ key: `review:${task.id}`, message: `Entrega pronta para revisar: ${task.title}` })),
    ...snapshot.tasks.filter((task) => task.status === "WAITING_APPROVAL").map((task) => ({ key: `approval:${task.id}`, message: `${task.title} precisa da sua decisão.` })),
    ...events.filter((event) => event.kind === "RUNNER_ERROR").map((event) => ({ key: `error:${event.id}`, message: String(event.payload.title ?? "Uma estação precisa de atenção.") })),
  ] : [], [snapshot, events]);
  const attentionSignature = attentionItems.map((item) => item.key).join("|");
  const primeAudio = () => {
    if (!soundEnabled) return;
    try { audioContext.current ??= new AudioContext(); void audioContext.current.resume(); } catch { /* Som é opcional. */ }
  };
  const playNotificationSound = () => {
    if (!soundEnabled) return;
    try {
      const context = audioContext.current ?? new AudioContext(); audioContext.current = context;
      const oscillator = context.createOscillator(); const gain = context.createGain(); const now = context.currentTime;
      oscillator.type = "sine"; oscillator.frequency.setValueAtTime(660, now); oscillator.frequency.setValueAtTime(880, now + .11);
      gain.gain.setValueAtTime(.0001, now); gain.gain.exponentialRampToValueAtTime(.12, now + .025); gain.gain.exponentialRampToValueAtTime(.0001, now + .34);
      oscillator.connect(gain); gain.connect(context.destination); oscillator.start(now); oscillator.stop(now + .36);
    } catch { /* A notificação visual continua disponível. */ }
  };
  useEffect(() => { const prime = () => primeAudio(); window.addEventListener("pointerdown", prime, { once: true }); return () => window.removeEventListener("pointerdown", prime); }, [soundEnabled]);
  useEffect(() => {
    if (!snapshot) return;
    const next = new Set(attentionItems.map((item) => item.key));
    if (seenAttention.current) {
      const added = attentionItems.find((item) => !seenAttention.current!.has(item.key));
      if (added) {
        setNotification(added.message); playNotificationSound();
        if (notificationTimer.current) window.clearTimeout(notificationTimer.current);
        notificationTimer.current = window.setTimeout(() => setNotification(null), 6_000);
      }
    }
    seenAttention.current = next;
    return () => { if (notificationTimer.current) window.clearTimeout(notificationTimer.current); };
  }, [attentionSignature]);
  const toggleSound = () => {
    const enabled = !soundEnabled; setSoundEnabled(enabled); localStorage.setItem("mireva:notification-sound", enabled ? "on" : "off");
    if (enabled) try { audioContext.current ??= new AudioContext(); void audioContext.current.resume(); } catch { /* A notificação visual continua disponível. */ }
  };
  const decide = async (task: Task, status: "DONE" | "WAITING_APPROVAL") => {
    if (!snapshot) return;
    const result = status === "DONE" ? "Aprovada pelo responsável" : window.prompt("Qual ajuste o agente precisa fazer?");
    if (result === null) return;
    try { const response = await fetch(`${hub}/rooms/${roomCode}/tasks/${task.id}/decision`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ownerId: snapshot.room.ownerId, status, result }) }); if (!response.ok) throw new Error("Não foi possível registrar a decisão"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível registrar a decisão"); }
  };
  const sendRequest = async () => {
    if (!snapshot || !requestText.trim()) return;
    try { const response = await fetch(`${hub}/rooms/${roomCode}/events`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ participantId: snapshot.room.ownerId, kind: "ORCHESTRATOR_REQUEST", payload: { message: requestText.trim() } }) }); if (!response.ok) throw new Error("Não foi possível enviar o pedido"); setRequestText(""); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível enviar o pedido"); }
  };
  const decidePlan = async (plan: OrchestrationPlanRecord, status: "APPROVED" | "REJECTED") => {
    if (!snapshot) return;
    try { const response = await fetch(`${hub}/rooms/${roomCode}/plans/${plan.id}/decision`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ownerId: snapshot.room.ownerId, status }) }); if (!response.ok) throw new Error("Não foi possível decidir o plano"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível decidir o plano"); }
  };
  const dispatchTasks = async () => {
    if (!snapshot) return;
    try { const response = await fetch(`${hub}/rooms/${roomCode}/tasks/dispatch`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ownerId: snapshot.room.ownerId }) }); if (!response.ok) throw new Error("Não foi possível distribuir as tarefas"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível distribuir as tarefas"); }
  };
  const updateProjectMemory = async (content: string) => {
    if (!snapshot) return;
    try { const response = await fetch(`${hub}/rooms/${roomCode}/memory`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ownerId: snapshot.room.ownerId, content }) }); if (!response.ok) throw new Error("Não foi possível salvar a memória do projeto"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível salvar a memória do projeto"); }
  };
  const configureParticipant = async (participant: Participant, role: (typeof roles)[number], capabilities: string[], permissionProfile: PermissionProfile) => {
    if (!snapshot) return;
    try {
      const response = await fetch(`${hub}/rooms/${roomCode}/participants/${participant.id}/config`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ownerId: snapshot.room.ownerId, role, capabilities, permissionProfile }) });
      if (!response.ok) throw new Error("Não foi possível atualizar a estação");
      await load();
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível atualizar a estação"); }
  };
  const messageAgent = async (participant: Participant, message: string) => {
    if (!snapshot || !message.trim()) return;
    try { const response = await fetch(`${hub}/rooms/${roomCode}/events`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ participantId: snapshot.room.ownerId, kind: "AGENT_MESSAGE", payload: { targetParticipantId: participant.id, message: message.trim() } }) }); if (!response.ok) throw new Error("Não foi possível enviar a mensagem"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível enviar a mensagem"); }
  };
  const reportUsage = async (participant: Participant, input: { used: number; limit: number; unit: string; resetAt: string | null }) => {
    if (!snapshot) return;
    try {
      const response = await fetch(`${hub}/rooms/${roomCode}/participants/${participant.id}/usage`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ reporterId: snapshot.room.ownerId, ...input }) });
      if (!response.ok) throw new Error("Não foi possível registrar o limite");
      await load();
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível registrar o limite"); }
  };
  const retryTask = async (taskId: string, permissionProfile?: PermissionProfile) => {
    if (!snapshot) return;
    try { const response = await fetch(`${hub}/rooms/${roomCode}/tasks/${taskId}/retry`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ownerId: snapshot.room.ownerId, permissionProfile }) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error ?? "Não foi possível tentar novamente"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível tentar novamente"); }
  };
  const updateStationPermission = async (participantId: string, permissionProfile: PermissionProfile, taskId?: string) => {
    const participant = snapshot?.participants.find((entry) => entry.id === participantId); if (!participant) return;
    await configureParticipant(participant, participant.role ?? "GENERAL", participant.capabilities ?? [], permissionProfile);
    if (taskId) await retryTask(taskId);
  };
  const ownerTaskAction = async (taskId: string, action: "cancel" | "intervene", message?: string) => {
    if (!snapshot) return;
    try { const response = await fetch(`${hub}/rooms/${roomCode}/tasks/${taskId}/${action}`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(action === "cancel" ? { ownerId: snapshot.room.ownerId, reason: message } : { ownerId: snapshot.room.ownerId, message }) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error ?? "Não foi possível atualizar a tarefa"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível atualizar a tarefa"); }
  };
  const pauseParticipant = async (participant: Participant, paused: boolean) => {
    if (!snapshot) return;
    try { const response = await fetch(`${hub}/rooms/${roomCode}/participants/${participant.id}/pause`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ownerId: snapshot.room.ownerId, paused }) }); if (!response.ok) throw new Error("Não foi possível alterar a pausa da estação"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível alterar a pausa da estação"); }
  };
  const gitCommand = async (participant: Participant, action: "STATUS" | "CREATE_BRANCH" | "COMMIT", extra: Record<string, string> = {}) => {
    if (!snapshot) return;
    try { const response = await fetch(`${hub}/rooms/${roomCode}/events`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ participantId: snapshot.room.ownerId, kind: "GIT_COMMAND", payload: { targetParticipantId: participant.id, action, ...extra } }) }); if (!response.ok) throw new Error("Não foi possível enviar o comando Git"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível enviar o comando Git"); }
  };
  return <main className={`office-app ${snapshot ? "has-sidebar" : ""}`}>
    {snapshot && <WorkspaceNavigation page={page} roomCode={roomCode} errorCount={runnerErrors.length} decisionCount={decisionCount} soundEnabled={soundEnabled} onToggleSound={toggleSound} onNavigate={navigate} onConnect={() => setShowRunnerConnect(true)} />}
    <section className="workspace-content">
    <header className={`topbar ${snapshot ? "compact" : ""}`}>{snapshot ? <><div className="topbar-project"><span>Projeto atual</span><strong>{snapshot.room.name}</strong></div><div className="topbar-status"><span className="live-dot" />Sala sincronizada</div></> : <><div><p className="eyebrow">MIREVA WORKSPACE <span>•</span> LIVE OFFICE</p><h1>Seu escritório de IAs</h1><p className="subtitle">Acompanhe a equipe, as tarefas e as decisões em um só lugar.</p></div><div className="topbar-status"><span className="offline-dot" />Aguardando conexão</div></>}</header>
    {notification && <button className="notification-toast" onClick={() => { setNotification(null); navigate("inbox"); }}><i><UiIcon icon={faCircleExclamation} /></i><span><b>Ação necessária</b>{notification}</span><strong>Ver decisões <UiIcon icon={faArrowRight} /></strong></button>}
    {error && <p className="error-message">{error}</p>}
    {showRoomSetup && <RoomSetup onCreate={createRoom} onEnter={enterRoom} onClose={roomCode ? () => setShowRoomSetup(false) : undefined} />}
    {showRunnerConnect && <RunnerConnectWizard roomCode={roomCode} hub={hub} onClose={() => setShowRunnerConnect(false)} />}
    {snapshot && <>
      {page === "office" && <><PageHeading eyebrow="VISÃO GERAL" title="Escritório" description="Veja a equipe trabalhando e abra qualquer estação para inspecionar." /><section className="stats" aria-label="Resumo do projeto"><Metric value={`${activeCount}/5`} label="agentes ativos" /><Metric value={snapshot.tasks.filter((task) => task.status === "RUNNING").length} label="em execução" /><Metric value={snapshot.tasks.filter((task) => task.status === "REVIEW").length} label="pedem decisão" /><Metric value={snapshot.tasks.filter((task) => task.status === "DONE").length} label="entregas feitas" /></section>
      <section className="workspace-layout"><div className="scene-card"><div className="scene-heading"><div><p className="eyebrow">ESCRITÓRIO VIRTUAL</p><h2>Equipe em tempo real</h2></div><span>{activeCount} agentes trabalhando agora</span></div><div className="office-scene pixel-office pixel-office-v2">
        <div className="office-wall"><div className="office-window window-a" /><div className="office-window window-b" /><img src="/sprites/office/Wall-Graph.png" className="wall-item graph-item" alt="" /><img src="/sprites/office/Wall-Clock.png" className="wall-item clock-item" alt="" /><img src="/sprites/office/Wall-Shelf.png" className="wall-item shelf-item" alt="" /><div className="project-display"><span>PROGRESSO DO PROJETO</span><strong>{snapshot.tasks.filter((task) => task.status === "DONE").length}<small> / {snapshot.tasks.length || 0}</small></strong><i><b style={{ width: `${snapshot.tasks.length ? Math.round((snapshot.tasks.filter((task) => task.status === "DONE").length / snapshot.tasks.length) * 100) : 0}%` }} /></i></div></div>
        <div className="office-floor" />
        <div className="room-label control-label">CENTRO DE CONTROLE</div><div className="room-label team-label">EQUIPE DE AGENTES</div><div className="room-label lounge-label">ÁREA DE PAUSA</div>
        <div className="control-room"><button className="orchestrator-station" onClick={() => { setSelectedId(null); navigate("orchestrator"); }} aria-label="Abrir chat do orquestrador"><img className="boss-desk-sprite" src="/sprites/office/Boss-Desk.png" alt="" /><img className="boss-chair-sprite" src="/sprites/office/Boss-Chair.png" alt="" /><img className="orchestrator-character" src="/sprites/characters/worker-right.gif" alt="" /><span className="orchestrator-status"><i /> ORQUESTRADOR</span><strong>Conversar e planejar</strong><small>Clique para abrir o chat</small></button><img className="control-bookshelf" src="/sprites/office/Tall-Bookshelf.png" alt="" /><img className="control-plant" src="/sprites/office/Big-Plant.png" alt="" /></div>
        <div className="team-room"><div className="desk-grid-v2">{desks.map((person, index) => <Desk key={person?.id ?? `slot-${index}`} person={person} task={person ? assigned.get(person.id) : undefined} index={index} selected={person?.id === selected?.id} away={Boolean(person && idleRunners.some((runner) => runner.id === person.id))} onSelect={() => { if (person) setSelectedId(person.id); }} />)}</div></div>
        <div className="lounge-room" aria-hidden="true"><img className="lounge-sofa" src="/sprites/office/Big-Sofa.png" alt="" /><img className="lounge-table" src="/sprites/office/Big-Round-Table.png" alt="" /><img className="lounge-vending" src="/sprites/office/Vending-Machine.png" alt="" /><img className="lounge-coffee" src="/sprites/office/Coffee-Machine.png" alt="" /><img className="lounge-water" src="/sprites/office/Water-Dispenser.png" alt="" /><img className="lounge-plant" src="/sprites/office/Small-Plant.png" alt="" /></div>
        {idleRunners.map((person, index) => <AmbientAgent key={person.id} person={person} agentIndex={officeRunners.findIndex((runner) => runner.id === person.id)} index={index} social={idleRunners.length > 1 && index < 2} selected={person.id === selected?.id} onSelect={() => setSelectedId(person.id)} />)}
        <div className="office-corridor"><span><UiIcon icon={faArrowsUpDown} /> CIRCULAÇÃO</span></div>
      </div><div className="scene-footer"><span><i /> Atualização ao vivo</span><span>Clique em uma mesa para ver a atividade</span><span>{activeCount} de 5 estações conectadas</span></div></div>
        <aside className="agent-panel">{selected ? <AgentDetails person={selected} task={selectedTask} events={events} onConfigure={configureParticipant} onMessage={messageAgent} /> : <ControlCenterCard snapshot={snapshot} onOpen={() => navigate("orchestrator")} />}</aside></section></>}
      {page === "orchestrator" && <><PageHeading eyebrow="CENTRO DE CONTROLE" title="Orquestrador" description="Converse, aprove o plano e acompanhe as decisões em um espaço próprio." /><OrchestratorWorkspace snapshot={snapshot} events={events} onClose={() => navigate("office")} onConnect={() => setShowRunnerConnect(true)} onConfigure={configureParticipant} onDecision={decide} onPlanDecision={decidePlan} onDispatch={dispatchTasks} onMemoryUpdate={updateProjectMemory} requestText={requestText} onRequestText={setRequestText} onRequest={sendRequest} /></>}
      {page === "inbox" && <><PageHeading eyebrow="CONTROLES HUMANOS" title="Caixa de decisões" description="Aprove planos e entregas, libere permissões ou intervenha antes que algo siga sozinho." /><DecisionInbox snapshot={snapshot} events={events} onPlanDecision={decidePlan} onDecision={decide} onRetry={retryTask} onCancel={(task) => { const reason = window.prompt("Motivo do cancelamento (opcional):") ?? undefined; void ownerTaskAction(task.id, "cancel", reason); }} onCorrect={(task) => { const message = window.prompt("Qual correção o agente deve aplicar?"); if (message?.trim()) void ownerTaskAction(task.id, "intervene", message); }} /></>}
      {page === "tasks" && <><PageHeading eyebrow="FLUXO DE TRABALHO" title="Tarefas" description="Acompanhe cada etapa do plano, das ideias às entregas aprovadas." /><section className="flow-section standalone-section"><div className="section-heading"><div><p className="eyebrow">QUADRO DO PROJETO</p><h2>Execução do plano</h2></div><span>{snapshot.tasks.length} tarefas no total</span></div><div className="task-flow">{taskStates.map((state) => <div className="flow-column" key={state}><h3>{taskStateLabel(state)} <small>{snapshot.tasks.filter((task) => task.status === state).length}</small></h3>{snapshot.tasks.filter((task) => task.status === state).map((task) => <TaskCard key={task.id} task={task} />)}{!snapshot.tasks.some((task) => task.status === state) && <p className="empty-state">Sem tarefas</p>}</div>)}</div></section><ActivityStream events={events} /></>}
      {page === "team" && <><PageHeading eyebrow="AGENTES CONECTADOS" title="Equipe" description="Veja quem está trabalhando e acompanhe os limites de cada IA." /><MonitoringPanel participants={snapshot.participants} assigned={assigned} onReport={reportUsage} onSelect={(participant) => { setSelectedId(participant.id); navigate("office"); }} onConnect={() => setShowRunnerConnect(true)} /></>}
      {page === "git" && <><PageHeading eyebrow="CONTROLE DE CÓDIGO" title="Git" description="Confira alterações, crie uma branch de trabalho e registre commits explicitamente." /><GitControlPage participants={snapshot.participants} events={events} onCommand={gitCommand} onPause={pauseParticipant} /></>}
      {page === "errors" && <><PageHeading eyebrow="CONFIABILIDADE" title="Erros e recuperação" description="Entenda o que aconteceu, corrija a causa e retome o trabalho sem perder o histórico." /><ErrorCenter snapshot={snapshot} events={events} onRetry={retryTask} onUpdateStationPermission={updateStationPermission} /></>}
      {page === "settings" && <><PageHeading eyebrow="PROJETO E CONEXÃO" title="Configurações" description="Gerencie a sala, o convite e o contexto compartilhado com as IAs." /><SettingsPage snapshot={snapshot} hub={hub} roomCode={roomCode} onConnect={() => setShowRunnerConnect(true)} onChangeRoom={() => setShowRoomSetup(true)} onMemoryUpdate={updateProjectMemory} onOpenGit={() => navigate("git")} /></>}
    </>}
    </section>
  </main>;
}
function WorkspaceNavigation({ page, roomCode, errorCount, decisionCount, soundEnabled, onToggleSound, onNavigate, onConnect }: { page: WorkspacePage; roomCode: string; errorCount: number; decisionCount: number; soundEnabled: boolean; onToggleSound: () => void; onNavigate: (page: WorkspacePage) => void; onConnect: () => void }) {
  const primaryItems: Array<{ id: WorkspacePage; label: string; icon: IconDefinition }> = [
    { id: "office", label: "Escritório", icon: faBuilding },
    { id: "orchestrator", label: "Orquestrador", icon: faWandMagicSparkles },
    { id: "inbox", label: decisionCount ? `Decisões (${decisionCount})` : "Decisões", icon: faInbox },
    { id: "tasks", label: "Tarefas", icon: faListCheck },
    { id: "team", label: "Equipe", icon: faUsers },
  ];
  const systemItems: Array<{ id: WorkspacePage; label: string; icon: IconDefinition }> = [
    { id: "errors", label: errorCount ? `Erros (${errorCount})` : "Erros", icon: faTriangleExclamation },
    { id: "settings", label: "Configurações", icon: faGear },
  ];
  const renderItems = (items: typeof primaryItems) => items.map((item) => <button key={item.id} className={page === item.id ? "active" : ""} onClick={() => onNavigate(item.id)}><i><UiIcon icon={item.icon} /></i><span>{item.label}</span></button>);
  return <nav className="workspace-nav" aria-label="Navegação principal"><div className="nav-brand"><b>M</b><div><strong>Mireva</strong><span>Workspace</span></div></div><div className="workspace-nav-room"><span><i /> Sala ativa</span><strong>{roomCode}</strong></div><p className="nav-section-label">Workspace</p><div className="workspace-nav-links">{renderItems(primaryItems)}</div><p className="nav-section-label system-label">Sistema</p><div className="workspace-nav-links system-links">{renderItems(systemItems)}</div><div className="nav-actions"><button className={`nav-sound ${soundEnabled ? "enabled" : ""}`} onClick={onToggleSound} title={soundEnabled ? "Desativar sons" : "Ativar sons"} aria-label={soundEnabled ? "Desativar sons de notificação" : "Ativar sons de notificação"}><UiIcon icon={soundEnabled ? faBell : faBellSlash} />{decisionCount > 0 && <b>{decisionCount}</b>}</button><button className="nav-connect" onClick={onConnect}><UiIcon icon={faPlus} /> Conectar IA</button></div></nav>;
}
function PageHeading({ eyebrow, title, description }: { eyebrow: string; title: string; description: string }) { return <header className="page-heading"><p className="eyebrow">{eyebrow}</p><h2>{title}</h2><p>{description}</p></header>; }
function Metric({ value, label }: { value: string | number; label: string }) { return <div className="metric"><strong>{value}</strong><span>{label}</span></div>; }
function RoomSetup({ onCreate, onEnter, onClose }: { onCreate: (name: string, ownerName: string) => void; onEnter: (value: string) => void; onClose?: () => void }) {
  const [mode, setMode] = useState<"create" | "enter">("create");
  const [name, setName] = useState("");
  const [ownerName, setOwnerName] = useState("");
  const [invite, setInvite] = useState("");
  return <div className="room-setup-backdrop"><section className="room-setup" aria-labelledby="room-setup-title"><div className="room-setup-art"><img src="/sprites/office/Boss-Desk.png" alt="" /><img src="/sprites/characters/worker-right.gif" alt="" /></div><div className="room-setup-copy"><p className="eyebrow">MIREVA WORKSPACE</p><h2 id="room-setup-title">Vamos abrir seu escritório</h2><p>Você não precisa configurar servidor, Hub ou arquivos internos. Escolha como quer começar.</p></div>{onClose && <button className="modal-close" onClick={onClose} aria-label="Fechar"><UiIcon icon={faXmark} /></button>}<div className="room-setup-tabs"><button className={mode === "create" ? "active" : ""} onClick={() => setMode("create")}>Criar escritório</button><button className={mode === "enter" ? "active" : ""} onClick={() => setMode("enter")}>Entrar em escritório</button></div>{mode === "create" ? <form className="room-setup-form" onSubmit={(event) => { event.preventDefault(); if (name.trim() && ownerName.trim()) onCreate(name.trim(), ownerName.trim()); }}><label>Nome do projeto<input value={name} onChange={(event) => setName(event.target.value)} placeholder="Ex.: Site do escritório Silva" autoFocus /></label><label>Seu nome<input value={ownerName} onChange={(event) => setOwnerName(event.target.value)} placeholder="Ex.: Renato" /></label><button disabled={!name.trim() || !ownerName.trim()}>Criar e abrir escritório <UiIcon icon={faArrowRight} /></button><small>Depois você conecta o Codex, Copilot ou outra IA com alguns cliques.</small></form> : <form className="room-setup-form" onSubmit={(event) => { event.preventDefault(); onEnter(invite); }}><label>Código ou convite da sala<input value={invite} onChange={(event) => setInvite(event.target.value)} placeholder="Ex.: 4CB426DF ou cole o link" autoFocus /></label><button disabled={!invite.trim()}>Entrar no escritório <UiIcon icon={faArrowRight} /></button><small>O código aparece no convite enviado por quem criou o projeto.</small></form>}<p className="room-setup-footnote">O Mireva cuida da conexão segura entre as máquinas. Você só escolhe o projeto e as IAs que vão trabalhar.</p></section></div>;
}

function RunnerConnectWizard({ roomCode, hub, onClose }: { roomCode: string; hub: string; onClose: () => void }) {
  const [name, setName] = useState("");
  const [agent, setAgent] = useState<"copilot" | "codex">("copilot");
  const [isOrchestrator, setIsOrchestrator] = useState(false);
  const [permissionProfile, setPermissionProfile] = useState<PermissionProfile>("PROJECT");
  const role = isOrchestrator ? "ORCHESTRATOR" : "GENERAL";
  const capabilities = isOrchestrator ? "ORCHESTRATE" : "CODE,RESEARCH,TEST,GIT";
  const [copied, setCopied] = useState(false);
  const [projectDirectory, setProjectDirectory] = useState(localProjectDirectory);
  const [starting, setStarting] = useState(false);
  const [localMessage, setLocalMessage] = useState("");
  const [diagnostic, setDiagnostic] = useState<DiagnosticResult | null>(null);
  const quote = (value: string) => `"${value.replaceAll("\"", "\\\"")}"`;
  const command = `npx --yes @renatojose7/mireva@latest connect ${roomCode || "CODIGO_DA_SALA"} --hub ${quote(hub)} --name ${quote(name || "Nome do agente")} --agent ${agent} --role ${role} --capabilities ${quote(capabilities.replaceAll(" ", ""))} --permissions ${permissionProfile}`;
  const inviteUrl = `${inviteBaseUrl}${window.location.pathname}?hub=${encodeURIComponent(hub)}&room=${encodeURIComponent(roomCode)}`;
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=${encodeURIComponent(inviteUrl)}`;
  const copy = async () => { try { await navigator.clipboard.writeText(command); setCopied(true); window.setTimeout(() => setCopied(false), 2_500); } catch { setCopied(false); } };
  const runDiagnostics = async () => { const response = await fetch(`${localAgentUrl}/diagnostics`, { method: "POST", headers: { "content-type": "application/json", "x-mireva-token": localAgentToken }, body: JSON.stringify({ hub, agent, projectDirectory, permissionProfile }) }); const result = await response.json() as DiagnosticResult & { error?: string }; if (!response.ok) throw new Error(result.error ?? "Não foi possível verificar este computador"); setDiagnostic(result); return result; };
  const startLocal = async () => { setStarting(true); setLocalMessage(""); try { const checked = await runDiagnostics(); if (!checked.ok) { setLocalMessage("Corrija os itens em vermelho antes de iniciar a estação."); return; } const response = await fetch(`${localAgentUrl}/connect`, { method: "POST", headers: { "content-type": "application/json", "x-mireva-token": localAgentToken }, body: JSON.stringify({ roomCode, hub, name, agent, role, capabilities: capabilities.split(",").map((value) => value.trim()).filter(Boolean), permissionProfile, projectDirectory }) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error ?? "Não foi possível iniciar o runner"); setLocalMessage("Runner iniciado nesta máquina. A estação aparecerá em alguns segundos."); } catch (cause) { setLocalMessage(cause instanceof Error ? cause.message : "Mireva Agent local indisponível. Use o comando copiado."); } finally { setStarting(false); } };
  return <div className="runner-modal-backdrop" role="presentation" onMouseDown={onClose}><section className="runner-modal" role="dialog" aria-modal="true" aria-labelledby="runner-connect-title" onMouseDown={(event) => event.stopPropagation()}><button className="modal-close" onClick={onClose} aria-label="Fechar"><UiIcon icon={faXmark} /></button><p className="eyebrow">CONEXÃO GUIADA</p><h2 id="runner-connect-title">Conecte uma IA a esta sala</h2><p className="runner-modal-intro">Dê um nome à estação, escolha a IA e inicie. O Mireva verifica este computador antes de conectar.</p>{!roomCode && <p className="wizard-warning">Abra uma sala antes de continuar.</p>}<div className="runner-form"><label>Nome da estação<input value={name} onChange={(event) => setName(event.target.value)} placeholder="Ex.: Copilot Frontend" autoFocus /></label><label>IA que vai trabalhar<select value={agent} onChange={(event) => { setAgent(event.target.value as "copilot" | "codex"); setDiagnostic(null); }}><option value="copilot">GitHub Copilot</option><option value="codex">ChatGPT Codex</option></select></label><label>Permissões iniciais<select value={permissionProfile} onChange={(event) => setPermissionProfile(event.target.value as PermissionProfile)}>{permissionProfiles.map((profile) => <option key={profile} value={profile}>{permissionInfo[profile].label}</option>)}</select><small>{permissionInfo[permissionProfile].description}</small></label>{!localProjectDirectory && <label className="project-folder">Pasta do projeto neste computador<input value={projectDirectory} onChange={(event) => { setProjectDirectory(event.target.value); setDiagnostic(null); }} placeholder="/home/voce/projetos/meu-site" /></label>}<label className="orchestrator-choice"><input type="checkbox" checked={isOrchestrator} onChange={(event) => { setIsOrchestrator(event.target.checked); setPermissionProfile(event.target.checked ? "READ_ONLY" : "PROJECT"); }} /> Esta é a IA que vai organizar o projeto <small>Marque uma única estação como orquestrador. As demais executam as tarefas atribuídas.</small></label></div>{diagnostic && <div className="diagnostic-list"><header><strong>Diagnóstico do computador</strong><span className={diagnostic.ok ? "ok" : "error"}>{diagnostic.ok ? "Pronto" : "Atenção"}</span></header>{diagnostic.checks.map((check) => <article key={check.key} className={check.status}><i><UiIcon icon={check.status === "ok" ? faCheck : check.status === "warning" ? faTriangleExclamation : faXmark} /></i><div><strong>{check.title}</strong><p>{check.detail}</p>{check.fix && <small>{check.fix}</small>}</div></article>)}</div>}<button className="diagnostic-button" disabled={!projectDirectory.trim() || starting} onClick={() => { setStarting(true); setLocalMessage(""); void runDiagnostics().catch((cause) => setLocalMessage(cause instanceof Error ? cause.message : "Diagnóstico indisponível")).finally(() => setStarting(false)); }}>Verificar computador</button><button className="start-local-button" disabled={!roomCode || !name.trim() || !projectDirectory.trim() || starting} onClick={() => void startLocal()}>{starting ? "Verificando…" : isOrchestrator ? "Verificar e iniciar orquestrador" : "Verificar e iniciar IA"}</button>{localMessage && <p className="local-message">{localMessage}</p>}<div className="invite-box"><div><span>CONVIDAR OUTRA MÁQUINA</span><p>No outro computador, abra o Mireva dentro da pasta do projeto e use este convite para entrar nesta sala.</p><code>{inviteUrl}</code></div><img src={qrUrl} alt="QR code do convite da sala" /></div><details className="advanced-connect"><summary>Usar o terminal em vez da tela</summary><div className="generated-command"><code>{command}</code><button disabled={!roomCode || !name.trim()} onClick={() => void copy()}>{copied ? <><UiIcon icon={faCheck} /> Copiado</> : <><UiIcon icon={faCopy} /> Copiar comando</>}</button></div></details><p className="runner-footnote">O Copilot ou Codex pedirá o login normal somente na primeira vez.</p></section></div>;
}
function Desk({ person, task, index, selected, away, onSelect }: { person: Participant | null; task?: Task; index: number; selected: boolean; away: boolean; onSelect: () => void }) {
  if (!person) return <div className={`desk-station-v2 desk-${index + 1} vacant`}><div className="workstation-art"><img className="desk-sprite-v2" src={index % 2 ? "/sprites/office/Desk-2.png" : "/sprites/office/Desk.png"} alt="" /><img className="chair-sprite-v2" src="/sprites/office/Chair.png" alt="" /><span className="vacant-plus-v2"><UiIcon icon={faPlus} /></span></div><div className="desk-label-v2"><small>ESTAÇÃO {String(index + 1).padStart(2, "0")}</small><strong>Livre</strong><span>Conectar agente</span></div></div>;
  const info = stateInfo[person.state] ?? stateInfo.DISCONNECTED;
  const role = roleInfo[person.role ?? "GENERAL"] ?? roleInfo.GENERAL;
  return <button className={`desk-station-v2 desk-${index + 1} ${selected ? "selected" : ""} ${away ? "agent-away" : ""}`} style={{ "--accent": info.color, "--character-hue": `${index * 47}deg` } as CSSProperties} onClick={onSelect} aria-pressed={selected}><div className="workstation-art"><img className="desk-sprite-v2" src={index % 2 ? "/sprites/office/Desk-2.png" : "/sprites/office/Desk.png"} alt="" /><img className="chair-sprite-v2" src="/sprites/office/Chair.png" alt="" />{!away && <img className="worker-character" src={index % 2 ? "/sprites/characters/worker-left.gif" : "/sprites/characters/worker-right.gif"} alt="" aria-hidden="true" />}{away && <span className="away-note"><UiIcon icon={faMugHot} /></span>}<span className="presence-light-v2" /></div><div className="desk-label-v2"><small>ESTAÇÃO {String(index + 1).padStart(2, "0")}</small><strong>{person.name}</strong><span>{role.label} · {away ? "Em pausa" : info.label}</span>{task && <em>{task.title}</em>}</div></button>;
}
function AmbientAgent({ person, agentIndex, index, social, selected, onSelect }: { person: Participant; agentIndex: number; index: number; social: boolean; selected: boolean; onSelect: () => void }) {
  return <button className={`ambient-agent ${social ? `social social-${index + 1}` : "walking"} ${selected ? "selected" : ""}`} style={{ "--character-hue": `${Math.max(0, agentIndex) * 47}deg`, "--wander-delay": `${index * -3.7}s`, "--wander-y": `${(index % 3) * 28}px` } as CSSProperties} onClick={onSelect} aria-label={`Abrir estação de ${person.name}`}><img src={index % 2 ? "/sprites/characters/worker-left.gif" : "/sprites/characters/worker-right.gif"} alt="" /><span>{person.name}</span>{social && <i>•••</i>}</button>;
}
function AgentDetails({ person, task, events, onConfigure, onMessage }: { person: Participant; task?: Task; events: RoomEvent[]; onConfigure: (participant: Participant, role: (typeof roles)[number], capabilities: string[], permissionProfile: PermissionProfile) => void; onMessage: (participant: Participant, message: string) => void }) {
  const info = stateInfo[person.state] ?? stateInfo.DISCONNECTED;
  const [role, setRole] = useState<(typeof roles)[number]>(person.role ?? "GENERAL");
  const [capabilities, setCapabilities] = useState((person.capabilities ?? []).join(", "));
  const [permissionProfile, setPermissionProfile] = useState<PermissionProfile>((person.permissionProfile as PermissionProfile | undefined) ?? (person.role === "ORCHESTRATOR" ? "READ_ONLY" : "PROJECT"));
  const [message, setMessage] = useState("");
  useEffect(() => { setRole(person.role ?? "GENERAL"); setCapabilities((person.capabilities ?? []).join(", ")); setPermissionProfile((person.permissionProfile as PermissionProfile | undefined) ?? (person.role === "ORCHESTRATOR" ? "READ_ONLY" : "PROJECT")); setMessage(""); }, [person]);
  const directConversation = events.filter((event) => ["AGENT_MESSAGE", "AGENT_RESPONSE"].includes(event.kind) && event.payload.targetParticipantId === person.id).slice(-8);
  const applyRole = () => onConfigure(person, role, capabilities.split(",").map((item) => item.trim().toUpperCase()).filter(Boolean), permissionProfile);
  const send = () => { if (!message.trim()) return; onMessage(person, message); setMessage(""); };
  return <><div className="panel-heading"><p className="eyebrow">ESTAÇÃO SELECIONADA</p><img className="agent-mark sprite-profile" src={pixelAvatarUrl(person.name)} alt="" /><h2>{person.name}</h2><p>{person.agent} <b>·</b> <UiIcon icon={roleInfo[role].icon} /> {roleInfo[role].label}</p><span className="state-chip" style={{ "--accent": info.color } as CSSProperties}><UiIcon icon={info.icon} /> {info.label}</span></div>
    <div className="task-focus"><span>TAREFA ATUAL</span>{task ? <><h3>{task.title}</h3><p>{task.description || "Sem descrição adicional."}</p><div className="progress-track"><i style={{ width: `${progressFor(task)}%`, background: info.color }} /></div><small>{progressFor(task)}% · {taskStateLabel(task.status)}</small></> : <p>Este agente está livre para receber a próxima tarefa.</p>}</div>
    {person.agent !== "human" && <><div className="agent-chat"><span>FALAR COM ESTA ESTAÇÃO</span><div>{directConversation.length ? directConversation.map((event) => <p key={event.id} className={event.kind === "AGENT_MESSAGE" ? "from-owner" : "from-agent"}><b>{event.kind === "AGENT_MESSAGE" ? "Você" : person.name}</b>{String(event.payload.message ?? "")}</p>) : <small>Envie uma pergunta ou instrução diretamente. O orquestrador poderá ver este histórico.</small>}</div><textarea value={message} onChange={(event) => setMessage(event.target.value)} placeholder={`Fale diretamente com ${person.name}…`} /><button disabled={!message.trim() || person.state === "DISCONNECTED"} onClick={send}>Enviar mensagem</button></div>
    <details className="station-config station-config-collapsed"><summary>Ajustes da estação</summary><div><label>Função<select value={role} onChange={(event) => { const next = event.target.value as (typeof roles)[number]; setRole(next); setCapabilities(roleInfo[next].capabilities.join(", ")); }}>{roles.map((entry) => <option key={entry} value={entry}>{roleInfo[entry].label}</option>)}</select></label><label>Capacidades<input value={capabilities} onChange={(event) => setCapabilities(event.target.value)} placeholder="CODE, TEST" /></label><label>Permissões<select value={permissionProfile} onChange={(event) => setPermissionProfile(event.target.value as PermissionProfile)}>{permissionProfiles.map((profile) => <option key={profile} value={profile}>{permissionInfo[profile].label}</option>)}</select><small>{permissionInfo[permissionProfile].description}</small></label><button onClick={applyRole}>Salvar ajustes</button></div></details></>}
  </>;
}
function MonitoringPanel({ participants, assigned, onReport, onSelect, onConnect }: { participants: Participant[]; assigned: Map<string, Task>; onReport: (participant: Participant, input: { used: number; limit: number; unit: string; resetAt: string | null }) => void; onSelect: (participant: Participant) => void; onConnect: () => void }) {
  const runners = participants.filter((participant) => participant.agent !== "human");
  const reported = runners.filter((participant) => participant.usage).length;
  return <section className="monitoring-section"><div className="section-heading"><div><p className="eyebrow">EQUIPE E LIMITES</p><h2>Estações conectadas</h2></div><div className="team-heading-actions"><span>{reported}/{runners.length} limites informados</span><button onClick={onConnect}><UiIcon icon={faPlus} /> Conectar IA</button></div></div><div className="runner-watch-list">{runners.map((person) => { const info = stateInfo[person.state] ?? stateInfo.DISCONNECTED; const usage = person.usage; const percent = usagePercent(usage); const task = assigned.get(person.id); return <article className="runner-watch" key={person.id}><header><button className="runner-identity" onClick={() => onSelect(person)}><img src={pixelAvatarUrl(person.name)} alt="" /><span><strong>{person.name}</strong><small>{person.agent} · {roleInfo[person.role]?.label ?? "Geral"} · visto {seenLabel(person.lastSeenAt)}</small></span></button><i style={{ background: info.color, boxShadow: `0 0 10px ${info.color}` }} /></header><p>{task?.title ?? (person.state === "DISCONNECTED" ? "Runner desconectado" : "Livre para receber tarefa")}</p>{usage && percent !== null ? <><div className={`limit-bar ${usageTone(usage)}`}><i style={{ width: `${percent}%` }} /></div><footer><b>{Math.max(0, 100 - percent)}% livre</b><span>{usage.used}/{usage.limit} {usage.unit} usados</span>{usage.resetAt && <em>reinicia {new Date(usage.resetAt).toLocaleDateString("pt-BR")}</em>}</footer></> : <footer className="limit-empty"><span>Limite ainda não informado</span></footer>}<details className="runner-limit-editor"><summary>{usage ? "Atualizar limite" : "Informar limite"}</summary><UsageDetails person={person} onReport={onReport} compact /></details></article>; })}{!runners.length && <div className="team-empty"><strong>Nenhuma IA conectada</strong><p>Conecte o primeiro orquestrador ou runner para começar.</p><button onClick={onConnect}><UiIcon icon={faPlus} /> Conectar primeira IA</button></div>}</div></section>;
}

function TeamDirectory({ participants, assigned, onSelect, onConnect }: { participants: Participant[]; assigned: Map<string, Task>; onSelect: (participant: Participant) => void; onConnect: () => void }) {
  const agents = participants.filter((participant) => participant.agent !== "human");
  return <section className="team-directory"><div className="section-heading"><div><p className="eyebrow">DIRETÓRIO DA EQUIPE</p><h2>Estações e funções</h2></div><button onClick={onConnect}><UiIcon icon={faPlus} /> Conectar IA</button></div><div className="team-directory-grid">{agents.map((person) => { const info = stateInfo[person.state] ?? stateInfo.DISCONNECTED; const task = assigned.get(person.id); return <button key={person.id} onClick={() => onSelect(person)} style={{ "--accent": info.color } as CSSProperties}><img src={pixelAvatarUrl(person.name)} alt="" /><div><strong>{person.name}</strong><span>{person.agent} · {roleInfo[person.role]?.label ?? "Geral"}</span><p>{task?.title ?? "Livre para receber tarefa"}</p></div><i /></button>; })}{!agents.length && <div className="team-empty"><strong>Nenhuma IA conectada</strong><p>Conecte o primeiro orquestrador ou runner para começar.</p><button onClick={onConnect}><UiIcon icon={faPlus} /> Conectar primeira IA</button></div>}</div></section>;
}

function ErrorCenter({ snapshot, events, onRetry, onUpdateStationPermission }: { snapshot: HubSnapshot; events: RoomEvent[]; onRetry: (taskId: string, permissionProfile?: PermissionProfile) => Promise<void>; onUpdateStationPermission: (participantId: string, permissionProfile: PermissionProfile, taskId?: string) => Promise<void> }) {
  const failures = events.filter((event) => event.kind === "RUNNER_ERROR").reverse();
  const recoveries = events.filter((event) => event.kind === "RUNNER_RECOVERED");
  const [copied, setCopied] = useState<string | null>(null);
  const diagnostic = { generatedAt: new Date().toISOString(), room: { code: snapshot.room.code, name: snapshot.room.name }, participants: snapshot.participants.filter((entry) => entry.agent !== "human").map(({ id, name, agent, role, state, permissionProfile, lastSeenAt }) => ({ id, name, agent, role, state, permissionProfile, lastSeenAt })), tasks: snapshot.tasks.map(({ id, title, status, attempts, maxAttempts, assignedParticipantId, result }) => ({ id, title, status, attempts, maxAttempts, assignedParticipantId, result })), errors: failures.map((event) => ({ id: event.id, participantId: event.participantId, createdAt: event.createdAt, ...event.payload })), recoveries: recoveries.map((event) => ({ createdAt: event.createdAt, ...event.payload })) };
  const download = async () => { let local: unknown = { available: false }; try { const health = await fetch(`${localAgentUrl}/health`, { headers: { "x-mireva-token": localAgentToken } }); const status = await health.json() as { sessions?: Array<{ id: string }> }; const logs = await Promise.all((status.sessions ?? []).map(async (session) => fetch(`${localAgentUrl}/sessions/${session.id}/log`, { headers: { "x-mireva-token": localAgentToken } }).then((response) => response.json()).catch(() => ({ id: session.id, error: "Log indisponível" })))); local = { ...status, logs }; } catch (cause) { local = { available: false, error: cause instanceof Error ? cause.message : String(cause) }; } const url = URL.createObjectURL(new Blob([JSON.stringify({ ...diagnostic, local }, null, 2)], { type: "application/json" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `mireva-diagnostico-${snapshot.room.code}.json`; anchor.click(); URL.revokeObjectURL(url); };
  const copy = async (event: RoomEvent) => { await navigator.clipboard.writeText(JSON.stringify({ createdAt: event.createdAt, participantId: event.participantId, ...event.payload }, null, 2)); setCopied(event.id); window.setTimeout(() => setCopied(null), 2_000); };
  return <section className="error-center"><div className="error-overview"><article><span>Falhas registradas</span><strong>{failures.length}</strong><small>O histórico permanece salvo na sala.</small></article><article><span>Recuperações automáticas</span><strong>{recoveries.length}</strong><small>Tarefas retomadas depois de quedas.</small></article><article><span>Estações com atenção</span><strong>{snapshot.participants.filter((person) => ["BLOCKED", "AUTH_REQUIRED", "RATE_LIMITED", "NO_NETWORK", "WAITING_PERMISSION", "DISCONNECTED"].includes(person.state)).length}</strong><small>Login, rede, permissão ou conexão.</small></article><button onClick={() => void download()}><UiIcon icon={faDownload} /> Baixar diagnóstico</button></div><div className="error-list">{failures.map((event) => { const failure = event.payload as Partial<RunnerError> & { requiredPermission?: PermissionProfile }; const participant = snapshot.participants.find((entry) => entry.id === event.participantId); const task = snapshot.tasks.find((entry) => entry.id === failure.taskId); const retryable = task && ["FAILED", "BLOCKED", "WAITING_APPROVAL"].includes(task.status); const requiredPermission = failure.requiredPermission ?? (failure.code === "NO_NETWORK" ? "PROJECT_NETWORK" : failure.code === "PERMISSION_REQUIRED" ? "FULL" : undefined); return <article className="error-card" key={event.id}><header><div><span>{failure.code ?? "RUNNER_ERROR"}</span><h3>{failure.title ?? "Falha do runner"}</h3></div><time>{new Date(event.createdAt).toLocaleString("pt-BR")}</time></header><p>{failure.message ?? "O runner informou uma falha sem descrição."}</p><dl><div><dt>Estação</dt><dd>{participant?.name ?? "Estação removida"}</dd></div><div><dt>Operação</dt><dd>{failure.operation ?? "Não informada"}</dd></div>{task && <div><dt>Tarefa</dt><dd>{task.title}</dd></div>}<div><dt>Próximo passo</dt><dd>{failure.suggestedAction ?? "Confira os detalhes técnicos."}</dd></div></dl><details><summary>Ver detalhes técnicos</summary><pre>{failure.technicalDetails || JSON.stringify(event.payload, null, 2)}</pre></details><footer><button className="secondary" onClick={() => void copy(event)}>{copied === event.id ? <><UiIcon icon={faCheck} /> Copiado</> : <><UiIcon icon={faCopy} /> Copiar diagnóstico</>}</button>{retryable && <button onClick={() => void onRetry(task.id)}>Tentar novamente</button>}{retryable && requiredPermission && <button onClick={() => void onRetry(task.id, requiredPermission)}>Liberar só nesta tarefa</button>}{retryable && requiredPermission && participant && <button className="warning" onClick={() => void onUpdateStationPermission(participant.id, requiredPermission, task.id)}>Aplicar à estação</button>}</footer></article>; })}{!failures.length && <div className="error-empty"><strong>Nenhum erro registrado</strong><p>Quando um runner falhar, esta página mostrará a causa, os detalhes e as ações de recuperação.</p></div>}</div></section>;
}

function SettingsPage({ snapshot, hub, roomCode, onConnect, onChangeRoom, onMemoryUpdate, onOpenGit }: { snapshot: HubSnapshot; hub: string; roomCode: string; onConnect: () => void; onChangeRoom: () => void; onMemoryUpdate: (content: string) => void; onOpenGit: () => void }) {
  const [copied, setCopied] = useState(false);
  const inviteUrl = `${inviteBaseUrl}${window.location.pathname}?hub=${encodeURIComponent(hub)}&room=${encodeURIComponent(roomCode)}#office`;
  const copyInvite = async () => { try { await navigator.clipboard.writeText(inviteUrl); setCopied(true); window.setTimeout(() => setCopied(false), 2_500); } catch { setCopied(false); } };
  return <div className="settings-grid"><section className="settings-card"><p className="eyebrow">SALA ATUAL</p><h3>{snapshot.room.name}</h3><div className="settings-code"><span>Código da sala</span><strong>{roomCode}</strong></div><p>Compartilhe o convite com quem vai conectar outra máquina ao projeto.</p><div className="settings-actions"><button onClick={() => void copyInvite()}>{copied ? <><UiIcon icon={faCheck} /> Convite copiado</> : <><UiIcon icon={faCopy} /> Copiar convite</>}</button><button className="secondary" onClick={onChangeRoom}>Trocar de sala</button></div></section><section className="settings-card"><p className="eyebrow">IA NESTA MÁQUINA</p><h3>Conectar uma estação</h3><p>O Mireva usa a pasta em que foi aberto. Escolha Codex ou Copilot e deixe a conexão rodando.</p><button onClick={onConnect}><UiIcon icon={faPlus} /> Conectar IA</button><small>{import.meta.env.VITE_MIREVA_PROJECT_DIR || "Pasta do projeto detectada pelo launcher"}</small></section><section className="settings-card settings-advanced"><p className="eyebrow">FERRAMENTA AVANÇADA</p><h3>Controle Git</h3><p>Consulte alterações ou crie branches e commits locais quando realmente precisar. Nada é enviado automaticamente.</p><button onClick={onOpenGit}><UiIcon icon={faCodeBranch} /> Abrir ferramentas Git</button></section><section className="settings-card settings-memory"><p className="eyebrow">CONTEXTO COMPARTILHADO</p><h3>Regras do projeto</h3><ProjectMemory content={snapshot.projectMemory ?? ""} onSave={onMemoryUpdate} /></section></div>;
}

function UsageDetails({ person, onReport, compact = false }: { person: Participant; onReport: (participant: Participant, input: { used: number; limit: number; unit: string; resetAt: string | null }) => void; compact?: boolean }) {
  const [used, setUsed] = useState(String(person.usage?.used ?? ""));
  const [limit, setLimit] = useState(String(person.usage?.limit ?? ""));
  const [unit, setUnit] = useState(person.usage?.unit ?? "créditos");
  const [resetAt, setResetAt] = useState(person.usage?.resetAt ? person.usage.resetAt.slice(0, 16) : "");
  useEffect(() => { setUsed(String(person.usage?.used ?? "")); setLimit(String(person.usage?.limit ?? "")); setUnit(person.usage?.unit ?? "créditos"); setResetAt(person.usage?.resetAt ? person.usage.resetAt.slice(0, 16) : ""); }, [person]);
  if (person.agent === "human") return null;
  const save = () => { const nextUsed = Number(used); const nextLimit = Number(limit); if (!Number.isFinite(nextUsed) || !Number.isFinite(nextLimit) || nextUsed < 0 || nextLimit <= 0) return; onReport(person, { used: nextUsed, limit: nextLimit, unit: unit.trim() || "créditos", resetAt: resetAt ? new Date(resetAt).toISOString() : null }); };
  const percent = usagePercent(person.usage);
  return <div className={`usage-config ${compact ? "compact" : ""}`}>{!compact && <><div><span>LIMITE DO PROVEDOR</span>{percent !== null ? <b>{percent}% usado</b> : <b>Configure quando souber seu saldo</b>}</div><p>Registro manual: cada provedor mostra créditos e janelas de uso de um jeito diferente.</p></>}<div className="usage-fields"><label>Usado<input type="number" min="0" value={used} onChange={(event) => setUsed(event.target.value)} placeholder="0" /></label><label>Limite<input type="number" min="1" value={limit} onChange={(event) => setLimit(event.target.value)} placeholder="100" /></label><label>Unidade<input value={unit} onChange={(event) => setUnit(event.target.value)} placeholder="créditos" /></label><label>Reinicia em<input type="datetime-local" value={resetAt} onChange={(event) => setResetAt(event.target.value)} /></label></div><button disabled={!limit || Number(limit) <= 0} onClick={save}>Salvar limite</button></div>;
}

function ProjectMemory({ content, onSave }: { content: string; onSave: (content: string) => void }) { const [draft, setDraft] = useState(content); useEffect(() => setDraft(content), [content]); return <div className="project-memory"><span>MEMÓRIA DO PROJETO</span><p>Decisões, regras e contexto que o orquestrador e os runners recebem automaticamente.</p><textarea value={draft} onChange={(event) => setDraft(event.target.value)} placeholder="Ex.: usar React, manter o visual sóbrio, não alterar a página inicial..." /><button disabled={draft === content} onClick={() => onSave(draft)}>Salvar memória</button></div>; }
function ControlCenterCard({ snapshot, onOpen }: { snapshot: HubSnapshot; onOpen: () => void }) {
  const orchestrator = snapshot.participants.find((participant) => participant.role === "ORCHESTRATOR");
  return <div className="control-center-card"><div className="panel-heading"><p className="eyebrow">CENTRO DE CONTROLE</p><span className="agent-mark orchestrator-mark">MI</span><h2>Orquestrador</h2><p>{orchestrator ? `${orchestrator.name} está conectado à sala.` : "Conecte uma IA para organizar o projeto."}</p></div><div className="control-center-status"><span>CONVERSA E PLANEJAMENTO</span><strong>{snapshot.plans.some((plan) => plan.status === "DRAFT") ? "Há um plano aguardando sua decisão" : "Pronto para receber seu pedido"}</strong><p>Use uma conversa dedicada para explicar o que você quer construir, revisar o plano e distribuir as tarefas.</p></div><button onClick={onOpen}>Abrir conversa com o orquestrador <UiIcon icon={faArrowUpRightFromSquare} /></button></div>;
}
function OrchestratorWorkspace({ snapshot, events, onClose, onConnect, onConfigure, onDecision, onPlanDecision, onDispatch, onMemoryUpdate, requestText, onRequestText, onRequest }: { snapshot: HubSnapshot; events: RoomEvent[]; onClose: () => void; onConnect: () => void; onConfigure: (participant: Participant, role: (typeof roles)[number], capabilities: string[], permissionProfile: PermissionProfile) => void; onDecision: (task: Task, status: "DONE" | "WAITING_APPROVAL") => void; onPlanDecision: (plan: OrchestrationPlanRecord, status: "APPROVED" | "REJECTED") => void; onDispatch: () => void; onMemoryUpdate: (content: string) => void; requestText: string; onRequestText: (value: string) => void; onRequest: () => void }) {
  const conversation = events.filter((event) => ["ORCHESTRATOR_REQUEST", "ORCHESTRATOR_RESPONSE"].includes(event.kind)).slice(-30);
  const draftPlan = snapshot.plans.find((plan) => plan.status === "DRAFT");
  const reviewTasks = snapshot.tasks.filter((task) => task.status === "REVIEW");
  const readyTasks = snapshot.tasks.filter((task) => task.status === "READY");
  const orchestrator = snapshot.participants.find((participant) => participant.role === "ORCHESTRATOR");
  const [orchestratorPermission, setOrchestratorPermission] = useState<PermissionProfile>((orchestrator?.permissionProfile as PermissionProfile | undefined) ?? "READ_ONLY");
  useEffect(() => setOrchestratorPermission((orchestrator?.permissionProfile as PermissionProfile | undefined) ?? "READ_ONLY"), [orchestrator?.id, orchestrator?.permissionProfile]);
  const answered = new Set(events.filter((event) => event.kind === "ORCHESTRATOR_RESPONSE").map((event) => String(event.payload.requestEventId ?? "")));
  const pendingRequest = [...events].reverse().find((event) => event.kind === "ORCHESTRATOR_REQUEST" && !answered.has(event.id));
  const disconnected = !orchestrator || orchestrator.state === "DISCONNECTED";
  return <section className="orchestrator-workspace" aria-labelledby="orchestrator-title"><header><div><p className="eyebrow">MIREVA <span>•</span> CENTRO DE CONTROLE</p><h2 id="orchestrator-title">Conversa com o orquestrador</h2><p>{snapshot.room.name} · {orchestrator?.name ?? "Aguardando orquestrador"}</p></div><button onClick={onClose}><UiIcon icon={faArrowLeft} /> Voltar ao escritório</button></header><div className="orchestrator-layout"><aside><div className="orchestrator-profile"><span className="agent-mark orchestrator-mark">MI</span><div><strong>Orquestrador</strong><small>{orchestrator ? `${orchestrator.agent} · ${stateInfo[orchestrator.state]?.label ?? orchestrator.state}` : "Nenhuma IA conectada"}</small></div></div><p className="orchestrator-sidebar-copy">Explique o resultado desejado. A IA propõe um plano; você aprova antes de qualquer runner executar.</p>{orchestrator && <div className="orchestrator-permissions"><span>ACESSO DO ORQUESTRADOR</span><select value={orchestratorPermission} onChange={(event) => setOrchestratorPermission(event.target.value as PermissionProfile)}>{permissionProfiles.map((profile) => <option key={profile} value={profile}>{permissionInfo[profile].label}</option>)}</select><small>{permissionInfo[orchestratorPermission].description}</small><button disabled={orchestratorPermission === ((orchestrator.permissionProfile as PermissionProfile | undefined) ?? "READ_ONLY")} onClick={() => onConfigure(orchestrator, "ORCHESTRATOR", orchestrator.capabilities ?? ["ORCHESTRATE"], orchestratorPermission)}>Salvar acesso</button></div>}<details className="project-context"><summary>Contexto e regras do projeto</summary><ProjectMemory content={snapshot.projectMemory ?? ""} onSave={onMemoryUpdate} /></details><div className="orchestrator-side-stats"><span><b>{snapshot.participants.filter((person) => person.agent !== "human").length}</b> IAs na sala</span><span><b>{snapshot.tasks.length}</b> tarefas</span></div></aside><main className="orchestrator-chat-room"><div className="chat-room-history">{conversation.length ? conversation.map((event) => <article key={event.id} className={event.kind === "ORCHESTRATOR_REQUEST" ? "chat-owner" : "chat-orchestrator"}><span>{event.kind === "ORCHESTRATOR_REQUEST" ? "Você" : "Orquestrador"}</span><p>{event.kind === "ORCHESTRATOR_REQUEST" ? String(event.payload.message ?? "Pedido enviado") : String((event.payload.orchestrator as { summary?: string } | undefined)?.summary ?? event.payload.message ?? "Plano atualizado")}</p></article>) : <div className="chat-empty"><span className="agent-mark orchestrator-mark">MI</span><h3>O que vamos construir?</h3><p>Descreva o objetivo do projeto com suas próprias palavras. O orquestrador vai transformar isso em um plano claro para sua aprovação.</p></div>}{pendingRequest && <article className={`chat-runner-status ${disconnected ? "chat-runner-offline" : ""}`}><span>{disconnected ? "CONEXÃO INTERROMPIDA" : "ORQUESTRADOR"}</span><p>{disconnected ? "Seu pedido ficou salvo, mas o orquestrador está desconectado. Reconecte a IA para continuar daqui." : <>Pensando na sua mensagem<span className="thinking-dots" aria-label="pensando">•••</span></>}</p>{disconnected && <button onClick={onConnect}>Reconectar orquestrador</button>}</article>}{draftPlan && <div className="chat-plan"><span>PLANO PROPOSTO · {draftPlan.tasks.length} TAREFAS</span><strong>{draftPlan.summary}</strong><ol>{draftPlan.tasks.map((task, index) => <li key={`${task.title}-${index}`}>{task.title}</li>)}</ol><div><button onClick={() => onPlanDecision(draftPlan, "APPROVED")}>Aprovar plano</button><button onClick={() => onPlanDecision(draftPlan, "REJECTED")}>Recusar</button></div></div>}{readyTasks.length ? <button className="chat-dispatch" onClick={onDispatch}>Distribuir {readyTasks.length} tarefa(s) aprovada(s)</button> : null}{reviewTasks.map((task) => <div className="chat-review" key={task.id}><strong>{task.title}</strong><p>{task.result ?? "Entrega aguardando sua revisão."}</p><button onClick={() => onDecision(task, "DONE")}>Aprovar</button><button onClick={() => onDecision(task, "WAITING_APPROVAL")}>Pedir ajuste</button></div>)}</div><div className="chat-composer"><textarea autoFocus value={requestText} onChange={(event) => onRequestText(event.target.value)} placeholder="Ex.: Crie uma landing page para um escritório de advocacia, com visual sóbrio e formulário de contato." onKeyDown={(event) => { if (event.key === "Enter" && (event.ctrlKey || event.metaKey) && requestText.trim()) onRequest(); }} /><div><small>Ctrl + Enter para enviar</small><button disabled={!requestText.trim()} onClick={onRequest}>Enviar <UiIcon icon={faPaperPlane} /></button></div></div></main></div></section>;
}
function OrchestratorDetails({ snapshot, events, onDecision, onPlanDecision, onDispatch, onMemoryUpdate, requestText, onRequestText, onRequest }: { snapshot: HubSnapshot; events: RoomEvent[]; onDecision: (task: Task, status: "DONE" | "WAITING_APPROVAL") => void; onPlanDecision: (plan: OrchestrationPlanRecord, status: "APPROVED" | "REJECTED") => void; onDispatch: () => void; onMemoryUpdate: (content: string) => void; requestText: string; onRequestText: (value: string) => void; onRequest: () => void }) { const reviewTasks = snapshot.tasks.filter((task) => task.status === "REVIEW"); const draftPlan = snapshot.plans.find((plan) => plan.status === "DRAFT"); const readyTasks = snapshot.tasks.filter((task) => task.status === "READY"); const conversation = events.filter((event) => ["ORCHESTRATOR_REQUEST", "ORCHESTRATOR_RESPONSE", "PLAN_CREATED"].includes(event.kind)).slice(-5); const agentCount = snapshot.participants.filter((participant) => participant.agent !== "human").length; return <><div className="panel-heading"><p className="eyebrow">CENTRO DE CONTROLE</p><span className="agent-mark orchestrator-mark">MI</span><h2>Chat do orquestrador</h2><p>Descreva o que você quer construir.</p><span className="state-chip neutral"><UiIcon icon={faWandMagicSparkles} /> Monitorando o projeto</span></div><div className="orchestrator-chat"><span>CONVERSA DO PROJETO</span><div className="conversation">{conversation.length ? conversation.map((event) => <p className={event.kind === "ORCHESTRATOR_REQUEST" ? "from-owner" : "from-orchestrator"} key={event.id}>{event.kind === "ORCHESTRATOR_REQUEST" ? String(event.payload.message ?? "Pedido enviado") : String((event.payload.orchestrator as { summary?: string } | undefined)?.summary ?? event.payload.message ?? "Plano criado")}</p>) : <p className="chat-hint">Conte o resultado que você deseja. O orquestrador transformará o pedido em um plano para sua aprovação.</p>}</div><textarea value={requestText} onChange={(event) => onRequestText(event.target.value)} placeholder="Ex.: Crie uma landing page para um escritório de advocacia..." /><button disabled={!requestText.trim()} onClick={onRequest}>Enviar ao orquestrador <UiIcon icon={faPaperPlane} /></button></div><details className="project-context"><summary>Contexto e regras do projeto</summary><ProjectMemory content={snapshot.projectMemory ?? ""} onSave={onMemoryUpdate} /></details>{draftPlan ? <div className="plan-card"><span>PLANO PROPOSTO · {draftPlan.tasks.length} TAREFAS</span><strong>{draftPlan.summary}</strong><ol>{draftPlan.tasks.map((task, index) => <li key={`${task.title}-${index}`}>{task.title}{task.dependencies.length ? <small> depende de {task.dependencies.map((dependency) => dependency + 1).join(", ")}</small> : null}</li>)}</ol><div><button onClick={() => onPlanDecision(draftPlan, "APPROVED")}>Aprovar plano</button><button onClick={() => onPlanDecision(draftPlan, "REJECTED")}>Recusar</button></div></div> : null}{readyTasks.length ? <button className="dispatch-button" onClick={onDispatch}>Distribuir {readyTasks.length} tarefa(s) pronta(s)</button> : null}<div className="task-focus"><span>PRÓXIMA DECISÃO</span><h3>{reviewTasks[0]?.title ?? "Nada aguardando aprovação"}</h3><p>{reviewTasks.length ? "Uma entrega está pronta para sua decisão." : "O fluxo está livre para continuar."}</p></div>{reviewTasks.map((task) => <div className="decision-card" key={task.id}><strong>{task.title}</strong><p>{task.result ?? "Entrega aguardando sua revisão."}</p><div><button onClick={() => onDecision(task, "DONE")}>Aprovar</button><button onClick={() => onDecision(task, "WAITING_APPROVAL")}>Pedir ajuste</button></div></div>)}<div className="detail-grid"><Detail label="Tarefas prontas" value={readyTasks.length} /><Detail label="Em revisão" value={reviewTasks.length} /><Detail label="Agentes" value={`${agentCount}/5`} /><Detail label="Eventos" value={snapshot.lastSequence} /></div></>;
}
function Detail({ label, value }: { label: string; value: string | number }) { return <div><span>{label}</span><strong>{value}</strong></div>; }
function TaskCard({ task }: { task: Task }) { return <article className="task-card"><span>P{task.priority}</span><h4>{task.title}</h4>{task.description && <p>{task.description}</p>}<footer>{task.assignedParticipantId ? "Com agente" : "Sem agente"}<b>{task.dependencies.length ? `${task.dependencies.length} dep.` : "Livre"}</b></footer></article>; }
function ActivityStream({ events }: { events: RoomEvent[] }) { const items = events.slice(-10).reverse(); const deliveries = events.filter((event) => typeof event.payload.delivery === "object").length; return <section className="activity-section"><div className="section-heading"><div><p className="eyebrow">ATIVIDADE AO VIVO</p><h2>O que a equipe está fazendo</h2></div><span>{deliveries} entrega(s) registradas · uso de créditos depende do provedor</span></div><div className="activity-list">{items.map((event) => <article key={event.id}><i className={`event-${event.kind.toLowerCase()}`} /><div><strong>{event.kind.replaceAll("_", " ")}</strong><p>{String((event.payload.event as { message?: string } | undefined)?.message ?? (event.payload.orchestrator as { summary?: string } | undefined)?.summary ?? (event.payload.task as { title?: string } | undefined)?.title ?? "Atualização registrada na sala")}</p></div><time>{new Date(event.createdAt).toLocaleTimeString("pt-BR")}</time></article>)}{!items.length && <p className="empty-state">Aguardando atividade na sala.</p>}</div></section>; }

function DecisionInbox({ snapshot, events, onPlanDecision, onDecision, onRetry, onCancel, onCorrect }: { snapshot: HubSnapshot; events: RoomEvent[]; onPlanDecision: (plan: OrchestrationPlanRecord, status: "APPROVED" | "REJECTED") => void; onDecision: (task: Task, status: "DONE" | "WAITING_APPROVAL") => void; onRetry: (taskId: string, permissionProfile?: PermissionProfile) => Promise<void>; onCancel: (task: Task) => void; onCorrect: (task: Task) => void }) {
  const plans = snapshot.plans.filter((plan) => plan.status === "DRAFT");
  const review = snapshot.tasks.filter((task) => task.status === "REVIEW");
  const blocked = snapshot.tasks.filter((task) => task.status === "WAITING_APPROVAL");
  const active = snapshot.tasks.filter((task) => ["CLAIMED", "RUNNING"].includes(task.status));
  const permissionRequests = events.filter((event) => event.kind === "PERMISSION_REQUESTED").slice(-8).reverse();
  return <section className="decision-inbox"><div className="inbox-summary"><article><span>Planos</span><strong>{plans.length}</strong></article><article><span>Entregas</span><strong>{review.length}</strong></article><article><span>Permissões</span><strong>{blocked.length}</strong></article><article><span>Em andamento</span><strong>{active.length}</strong></article></div>
    <div className="inbox-grid"><section><header><p className="eyebrow">PLANEJAMENTO</p><h3>Planos para aprovar</h3></header>{plans.map((plan) => <article className="decision-item" key={plan.id}><strong>{plan.summary}</strong><p>{plan.tasks.length} tarefas propostas.</p><div><button onClick={() => onPlanDecision(plan, "APPROVED")}>Aprovar plano</button><button className="secondary" onClick={() => onPlanDecision(plan, "REJECTED")}>Recusar</button></div></article>)}{!plans.length && <p className="decision-empty">Nenhum plano aguardando decisão.</p>}</section>
      <section><header><p className="eyebrow">ENTREGAS</p><h3>Revisar trabalho</h3></header>{review.map((task) => <article className="decision-item" key={task.id}><strong>{task.title}</strong><p>{task.result ?? "O agente enviou uma entrega para revisão."}</p><div><button onClick={() => onDecision(task, "DONE")}>Aprovar</button><button className="secondary" onClick={() => onCorrect(task)}>Pedir correção</button></div></article>)}{!review.length && <p className="decision-empty">Nenhuma entrega aguardando revisão.</p>}</section>
      <section><header><p className="eyebrow">PERMISSÕES E BLOQUEIOS</p><h3>Retomar com controle</h3></header>{blocked.map((task) => <article className="decision-item" key={task.id}><strong>{task.title}</strong><p>{task.result ?? "A tarefa precisa da sua intervenção."}</p><div><button onClick={() => void onRetry(task.id)}>Tentar novamente</button><button className="secondary" onClick={() => onCorrect(task)}>Corrigir instrução</button><button className="danger" onClick={() => onCancel(task)}>Cancelar</button></div></article>)}{!blocked.length && <p className="decision-empty">Nenhuma permissão ou bloqueio pendente.</p>}{permissionRequests.length ? <details className="inbox-events"><summary>{permissionRequests.length} pedido(s) de permissão no histórico</summary>{permissionRequests.map((event) => <p key={event.id}>{String(event.payload.reason ?? event.payload.errorCode ?? "Permissão solicitada")}</p>)}</details> : null}</section>
      <section><header><p className="eyebrow">INTERVENÇÃO</p><h3>Parar ou redirecionar</h3></header>{active.map((task) => <article className="decision-item" key={task.id}><strong>{task.title}</strong><p>{task.status === "RUNNING" ? "A IA está executando agora." : "A tarefa está assumida e prestes a começar."}</p><div><button className="secondary" onClick={() => onCorrect(task)}>Enviar correção</button><button className="danger" onClick={() => onCancel(task)}>Cancelar tarefa</button></div></article>)}{!active.length && <p className="decision-empty">Nenhuma tarefa em execução neste momento.</p>}<small className="inbox-note">A correção interrompe a execução atual e devolve a tarefa à fila. O cancelamento não apaga arquivos já alterados.</small></section></div></section>;
}

function GitControlPage({ participants, events, onCommand, onPause }: { participants: Participant[]; events: RoomEvent[]; onCommand: (participant: Participant, action: "STATUS" | "CREATE_BRANCH" | "COMMIT", extra?: Record<string, string>) => void; onPause: (participant: Participant, paused: boolean) => Promise<void> }) {
  const runners = participants.filter((participant) => participant.agent !== "human" && participant.role !== "ORCHESTRATOR");
  const responses = events.filter((event) => event.kind === "GIT_RESPONSE").slice(-20).reverse();
  const status = (person: Participant) => onCommand(person, "STATUS");
  const branch = (person: Participant) => { const value = window.prompt("Nome da nova branch", `mireva/${person.name.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`); if (value?.trim()) onCommand(person, "CREATE_BRANCH", { branch: value.trim() }); };
  const commit = (person: Participant) => { const message = window.prompt("Mensagem do commit"); if (!message?.trim()) return; if (window.confirm("O Mireva vai executar git add -A e criar um commit local. Nada será enviado ao GitHub. Continuar?")) onCommand(person, "COMMIT", { message: message.trim() }); };
  return <section className="git-control"><div className="git-notice"><strong>Controle explícito</strong><p>O Mireva nunca faz push, merge ou resolve conflitos sozinho. Você manda cada comando e a estação responde com o resultado.</p></div><div className="git-runners">{runners.map((person) => <article key={person.id}><img src={pixelAvatarUrl(person.name)} alt="" /><div><strong>{person.name}</strong><span>{person.agent} · {person.paused ? "Pausado" : stateInfo[person.state]?.label ?? person.state}</span></div><footer><button disabled={person.state === "DISCONNECTED" || person.paused} onClick={() => status(person)}>Ver alterações</button><button disabled={person.state === "DISCONNECTED" || person.paused} onClick={() => branch(person)}>Criar branch</button><button className="secondary" disabled={person.state === "DISCONNECTED" || person.paused} onClick={() => commit(person)}>Criar commit</button><button className="secondary" onClick={() => void onPause(person, !person.paused)}>{person.paused ? "Retomar estação" : "Pausar após tarefa"}</button></footer></article>)}{!runners.length && <p className="decision-empty">Conecte um runner de desenvolvimento para usar os controles Git.</p>}</div><div className="git-results"><header><p className="eyebrow">RETORNOS DAS ESTAÇÕES</p><h3>Histórico Git</h3></header>{responses.map((event) => { const person = participants.find((participant) => participant.id === event.payload.targetParticipantId); const ok = event.payload.ok === true; return <article className={ok ? "git-result success" : "git-result failure"} key={event.id}><strong>{person?.name ?? "Estação"} · {String(event.payload.action ?? "GIT")}</strong><span>{ok ? "Concluído" : "Falhou"} · {new Date(event.createdAt).toLocaleTimeString("pt-BR")}</span><pre>{String(event.payload.output ?? event.payload.error ?? "Sem saída")}</pre></article>; })}{!responses.length && <p className="decision-empty">Envie “Ver alterações” a uma estação para começar.</p>}</div></section>;
}

createRoot(document.getElementById("root")!).render(<App />);
